// onchain-verify — render the daily health report.
// Judged per metric on the metric's OWN clock (onchain.metrics.max_staleness_ms, migration 003).
// Every failing check NAMES its metrics: a bare count cannot be acted on, and could not be told
// apart from the permanent floor the old one-threshold-for-everything check produced (L-3).
const r = $('Verify query').first().json;
const num = (x) => Number(x || 0);

const stale = num(r.stale_metrics);
const never = num(r.never_seen_metrics);
const unbounded = num(r.unbounded_metrics);
const orphans = num(r.orphans);
// A derived metric is HEALED, not healthy: the series has no gap, but a vendor stopped sending a
// field and someone must either chase that or retire the metric. Unlike L-3's permanent floor this
// is a real, closable condition, so it belongs in `ok` rather than being reported as background.
const derived = num(r.derived_metrics);
const ok = stale === 0 && never === 0 && unbounded === 0 && orphans === 0 && derived === 0;

const lines = [
  (ok ? '✅' : '⚠️') + ' onchain-verify (daily)',
  'rows: ' + r.total_rows + ' · buckets: ' + r.buckets,
  'metrics: ' + r.metrics_seen + '/' + r.metrics_registered + ' seen',
  'latest: ' + r.latest_ts_utc + ' UTC',
];
if (stale) lines.push('⏳ stale (age > registry bound): ' + r.stale_names);
if (never) lines.push('👻 registered but never written: ' + r.never_seen_names);
if (unbounded) lines.push('❓ no max_staleness_ms in registry: ' + r.unbounded_names);
if (derived) lines.push('🧮 derived — vendor field missing, value computed: ' + r.derived_names);
if (orphans) lines.push('🔗 orphan rows (asset/metric not in registry): ' + orphans);

// L-4: the Report node sends with parse_mode=HTML, so this text MUST be HTML-escaped. Metric ids
// are snake_case and every '_' is an italic delimiter under Telegram's Markdown modes — naming the
// offenders (the whole point of L-3) is what made an unescaped message a guaranteed 400
// "can't parse entities". '&' first, or it would double-escape the entities produced after it.
const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

let text = esc(lines.join('\n'));

// Telegram hard-caps a message at 4096 chars and the name lists are DB-derived, so bound them.
// Truncate AFTER escaping, then drop a half-written entity at the cut — a trailing '&am' would
// itself be an unparseable entity, i.e. the exact failure this guard exists to avoid.
if (text.length > 3500) {
  text = text.slice(0, 3500).replace(/&[a-z]{0,5}$/i, '') + '\n… truncated';
}

return [{ json: { ok, text } }];
